#ifndef INCLUDE_SCHEDULER_H_
#define INCLUDE_SCHEDULER_H_

#include <type.h>
#include <os/smp.h>
#include <os/list.h>
#include <os/mm.h>
#include <os/time.h>

#define NUM_MAX_TASK 16

/* used to save register infomation */
typedef struct regs_context
{
    /* Saved main processor registers.*/
    reg_t regs[32];

    /* Saved special registers. */
    reg_t sstatus;
    reg_t sepc;
    reg_t stval;
    reg_t scause;
    reg_t sscratch;
} regs_context_t;

typedef enum {
    TASK_BLOCKED,
    TASK_RUNNING,
    TASK_READY,
    TASK_ZOMBIE,
    TASK_EXITED,
    TASK_KILLED,
} task_status_t;

typedef enum {
    ENTER_ZOMBIE_ON_EXIT,
    AUTO_CLEANUP_ON_EXIT,
} spawn_mode_t;

typedef enum {
    KERNEL_PROCESS,
    KERNEL_THREAD,
    USER_PROCESS,
    USER_THREAD,
} task_type_t;

/* Process Control Block */
typedef struct pcb
{
    /* register context */
    // this must be this order!! The order is defined in regs.h
    reg_t kernel_sp;
    reg_t user_sp;

    // count the number of disable_preempt
    // enable_preempt enables CSR_SIE only when preempt_count == 0
    reg_t preempt_count;

    ptr_t kernel_stack_base;
    ptr_t user_stack_base;

    /* previous, next pointer and wait queue*/
    list_node_t list;
    list_head wait_list;

    /* acquired binsem lock */
    int binsem_id[100];
    int binsem_num;

    /* sleep timer */
    timer_t timer;

    /* process id */
    pid_t pid;

    /* kernel/user thread/process */
    task_type_t type;

    /* BLOCK | READY | RUNNING | ZOMBIE */
    task_status_t status;
    spawn_mode_t mode;

    /* priority and wait time */
    uint8_t priority;
    uint64_t ready_tick;

    /* hart mask */
    unsigned long mask;
    unsigned long cpu_id;

    /* cursor position */
    int cursor_x;
    int cursor_y;
} pcb_t;

/* task information, used to init PCB */
typedef struct task_info
{
    ptr_t entry_point;
    task_type_t type;
    uint8_t priority;
} task_info_t;

/* ready queue to run */
extern list_head ready_queue;
extern list_head sleep_queue;

/* current running task PCB */
extern pcb_t * volatile current_running[NR_CPUS];
extern pcb_t * volatile current_cpu_running;
extern pid_t process_id;

extern pcb_t pcb[NUM_MAX_TASK];
extern pcb_t kernel_pcb[NR_CPUS];
extern const pcb_t *core0_tp;
extern const pcb_t *core1_tp;
extern const ptr_t kernel_stack_0;
extern const ptr_t kernel_stack_1;

extern void scheduler(void);

extern pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode);
extern void do_exit(void);
extern void do_sleep(uint32_t);

extern int do_kill(pid_t pid);
extern int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs);
extern void do_process_show();
