int do_taskset(pid_t pid, unsigned long mask)
{
    // search the pcb
    pcb_t *set_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            set_pcb = &pcb[i];
